#!/usr/bin/env python3
"""Author research records only; never imports or executes candidate code."""
import json, shutil, datetime
from pathlib import Path
P=Path(__file__).resolve().parent
S=json.loads((P/'sources.json').read_text())
D={s['id']:s for s in S}
def ref(*ids):return ' '.join(f'[{i}]({D[i]["url"]})' for i in ids)
def v(id,text,*src):return text+' '+ref(*([id+'_'+x for x in src] if src else []))
C=[]
def card(id,name,owner,novelty,problem,delta,module,io,runtime,export,cost,rights,maintenance,integration,recommendation,test,deep=False):
    sid=[s['id'] for s in S if s['id'].startswith(id+'_')]
    if id=='R03':sid+=['RW_TROIKA']
    if id=='R09':sid+=['RW_MPL']
    if id=='R07':sid+=['RW_ZDOG']
    base=D[id+'_README']['url'].split('/blob/')[0]
    C.append(dict(id=id,name=name,url=base,owner=owner,pin=D[id+'_README']['pin'],reviewed='2026-11-11',**{'class':'A'},novelty=novelty,problem=problem,baseline_delta=delta+' Ocena dotyczy odczytanego baseline Studio/Toolbox/Open Assets; FrameMotion baseline Unknown.',module=module,io=io,runtime=runtime,export=export,cost=cost,rights=rights,maintenance=maintenance,evidence='DOCUMENTED + CODE_INSPECTED wskazane pliki; deklaracje autora i issue reports nie są pomiarem. OWN_TEST brak; wykonanie NOT_RUN. Rekomendacja, czas integracji i test są DERIVED.',target_owner='DERIVED: FrameMotion jako właściciel wąskiego adaptera, po ustaleniu jego API; Studio koordynuje i utrzymuje regułę/QA. Toolbox tylko przyszła kwalifikacja adaptera, nie automatyczne dodanie biblioteki.',integration=integration,recommendation=recommendation,test='NOT_RUN / DERIVED: '+test,source_ids=sid,deep_dive=deep,execution_status='NOT_RUN',card_path='agents/runtime/CARDS.md'))
PERM='Film: licencja silnika nie stanowi licencji wejściowych mediów; własna geometria może być renderowana komercyjnie, a font/asset wymaga osobnej zgody. Redystrybucja kodu: zachować właściwe notice. Assety, fonty, modele i media galerii: Unknown per plik, nie bundlować. Przykłady kodowe objęte repo notice tylko gdy brak osobnej licencji; linkowane dema nie są automatycznie objęte.'
EXPORT='DERIVED: deterministyczny stan → istniejący renderer/capture → sekwencja PNG → istniejący encoder MP4 albo WebM. Nie ma własnego encodera; alfa zależy od render target/capture/kodeka. EXR nieudokumentowane. Zgodność Remotion/HyperFrames/FFmpeg to plan adaptera, nie sprawdzona integracja.'
LIMIT=' Dokładny OS/browser/headless, RAM, VRAM i wydajność Unknown; nic nie zostało zainstalowane.'
card('R01','flubber — morph pojedynczego zamkniętego konturu','veltman / Noah Veltman','KNOWN_NEW_CAPABILITY','Morph figur o różnej liczbie punktów bez ręcznego dopasowania węzłów.','Baseline ma MorphSVG; delta to mały, niezależny interpolator pierścieni dla danych SVG/Canvas, bez wymogu GSAP. Nie uzasadnia zastąpienia istniejącego morph engine.',v('R01','src/interpolate.js, normalize.js, svg.js; interpolate(from,to,{maxSegmentLength,string}).','SRC01','SRC02','SRC03'),v('R01','IN path string lub ring [[x,y]]; OUT funkcja t→path/ring. T jest absolutnym postępem, edytowalne punkty i kolor przez host. Otwory i kolejne subpath są ignorowane; alfa N/A w geometrii.','README','SRC03'),v('R01','JS CPU, browser/Node. Pomiar krzywych używa native SVG w browser, a svg-path-properties poza nim, co wymaga testu cross-runtime. Brak potrzeby GPU do geometrii.'+LIMIT,'SRC03'),EXPORT,v('R01','Kod bez opłat/konta/klucza; offline po lokalnym przypięciu deps. Manifest 0.4.2: d3-array, d3-polygon, earcut, svg-path-properties ^0.2.1, svgpath, topojson-client. Skrypty test/build, bez install/postinstall/prepare w tym manifeście; build używa starego Rollup/Babel/Uglify. Adaptacja DERIVED 1–2 dni, nie obejmuje napraw upstream.','PACKAGE'),v('R01','MIT. '+PERM,'LICENSE'),v('R01','HEAD 2019-10-16; 0.4.2. Stary toolchain i import problem #108 (report, nie reproduced); endpoint string wraca w pobliżu 0/1, środek jest aproksymacją, więc trzeba sprawdzić skok i gładkość.','META','ISSUE108','SRC01'),'ADAPTER','P1: opcjonalny adapter prostych wypełnionych konturów. Odrzucać wielokonturowe litery/logo; użyć obecnej ścieżki MorphSVG lub ręcznej geometrii po jawnym wyborze, nie po cichu.','Trójkąt→kropla 2 s/60 klatek, krzywa i ring; odczyt [0,59,1,30,59,0], hash geometrii i obrazu; 16:9/9:16, maxSegmentLength 10/2; donut jako negative fixture musi dać UNSUPPORTED, nie zgubić otworu. Ogląd co klatkę, szczególnie 0→1 i 58→59.',True)
card('R02','svg-path-properties — pomiar ścieżki poza DOM','rveciana / Roger Veciana i Rovira','KNOWN_NEW_CAPABILITY','Ruch znacznika z prędkością według długości ścieżki i orientacją stycznej w Canvas/Node.','DrawSVG i ruch po path istnieją w GSAP; delta to geometry-only pomiar w Node i dostęp do segmentów. Współzależny z R01, nie liczyć dwóch pełnych nowych możliwości.',v('R02','src/main.ts: svgPathProperties, getTotalLength/getPointAtLength/getTangentAtLength/getParts.','SRC01'),v('R02','IN SVG d; OUT length, x/y, tangent, segment parameters. Host liczy distance=progress*length; brak własnego zegara/mediów; dane edytowalne, alfa N/A.','README','SRC01'),v('R02','JS CPU browser/Node; manifest 2.2.0 wymaga Node >=22. Zero deklarowanych runtime dependencies; żaden install hook w scripts. Bez DOM/GPU dla pomiaru.'+LIMIT,'PACKAGE','README'),EXPORT,v('R02','Brak konta/klucza/usługi; lokalna biblioteka offline po instalacji. DERIVED 0.5–1 dzień adaptera + wyjaśnienie praw.','PACKAGE'),v('R02','CONFLICT: package.json deklaruje ISC, LICENSE zawiera MIT. Nie rozstrzygamy przez zgadywanie; przed bundlowaniem źródeł/tarballa wyjaśnić upstream i przypiąć konkretne notice. Film z własną ścieżką i redystrybucja samego modułu to osobne użycia; media/fonty/modele/przykłady zewnętrzne Unknown.','PACKAGE','LICENSE'),v('R02','HEAD 2026-10-15, 2.2.0. Wersja w R01 to stara ^0.2.1, więc nie podmieniać transitive dependency automatycznie. Przybliżenia krzywych i zerowe segmenty wymagają próby.','META'),'OPTIONAL_DEPENDENCY','P1 warunkowo; wartościowy geometry helper, admission wstrzymane przez niespójne oznaczenie praw.','Sześcienny Bézier, łuk, cusp i zerowa długość; równe odstępy czasowe→równe odcinki łuku w tolerancji ustalonej na fixture; kierunek bez NaN, rewind; 16:9/9:16; overlay ścieżki i stycznych co klatkę.')
card('R03','troika-three-text — gotowość i SDF tekstu w Three.js','protectwise / Jason Johnston','KNOWN_NEW_CAPABILITY','Czytelny tekst w przestrzeni 3D, z układem i rasteryzacją znaków zarządzanymi przed capture.','Baseline zna Three i kinetic text; delta to konkretny text mesh SDF, readiness cache i lokalny font policy, nie cały framework Troika.',v('R03','packages/troika-three-text/src/Text.js, TextBuilder.js, FontResolver.js; Text.sync, configureTextBuilder, preloadFont.','SRC03','SRC04','SRC05','SRC02'),v('R03','IN zatwierdzony tekst, font URL, size/maxWidth/anchors/styleRanges/clipRect; OUT mesh i textRenderInfo. Transformacje można wyznaczać z frame; layout asynchroniczny. sync callback jest tylko w gałęzi _needsSync, więc bezwarunkowe Promise(sync) przy każdym frame może wisieć dla unchanged text. SDF nie jest font outline do dalszej edycji.','SRC03'),v('R03','Browser DOM + Three >=0.125.0 peer, WebGL i web worker domyślnie; useWorker=false jest opcją, nie usuwa wymogu browser canvas. Większe sdfGlyphSize zwiększa atlas/pamięć. Headless, OS i GPU trzeba przypiąć; RAM Unknown.','SRC01','SRC04'),EXPORT,v('R03','MIT kod bez konta/klucza. Offline NIE jest gwarantowane: FontResolver wysyła XHR i uruchamia unicode fallback. #394 opisuje CDN fallback mimo self-host URL; dokładna transitive polityka nie została wykonana. Subpackage: bidi-js, troika-three-utils, troika-worker-utils, webgl-sdf-generator; brak lifecycle install hook w subpackage. Root postinstall=lerna bootstrap, więc nie instalować całego monorepo. DERIVED 2–4 dni plus font QA.','SRC01','PACKAGE','SRC05','ISSUE394'),v('R03','MIT kod; font pliki i automatyczne fallbacki mają własne prawa Unknown. '+PERM,'LICENSE'),v('R03','HEAD 2026-11-02, subpackage 0.53.1. #398 raportuje font failure pozostawiający pending callbacks, #394 żąda wyłączenia sieci. Kod error path loguje bez zakończenia callback; raporty nie były reproduced. Dokumentacja opisuje dispose i workaround OverrideMaterialManager dla postprocessing.','META','ISSUE398','ISSUE394','SRC05','SRC02'),'ADAPTER','P0 research spike: lokalny font manifest, preflight coverage, timeout, cache gotowego layoutu; render tylko po ready. Brak fontu/coverage → jawny FAIL, bez ukrytej zamiany fontu. Nie dopuszczać arbitrary unicode online w eksportach offline.','Zażółć gęślą jaźń; NFC/NFD, łączona ligatura i brakujący glyph. Cold/warm load, unchanged text sync, błędny URL i sieć zablokowana. Wersjonowany cache key, bounds i full-frame movie 16:9/9:16, seek [0,47,1,47,0], clipping/alpha/SDF na czarnym i białym tle. Timeout nie może zapisać pustej klatki jako PASS.',True)
card('R04','postprocessing — wąski profil bloom/outline dla Three.js','pmndrs / Raoul van Rüschen','KNOWN_NEW_CAPABILITY','Spójne bloom/outline/grade istniejącej sceny Three przy kontrolowanej przestrzeni barw i czasie.','Baseline ma Three, pixel effects i transitions; delta to celowana kompozycja obrazu 3D, nie kolejny renderer ani katalog wszystkich efektów.',v('R04','src/core/EffectComposer.js + passes/EffectPass.js; do pilota statyczne efekty z istniejącej sceny. GlitchEffect.js jako kontrprzykład arbitrary seek.','SRC01','SRC02','SRC03'),v('R04','IN Three scene/render buffers, efekty/uniformy; OUT GPU obraz. composer.render(deltaTime) to delta, nie czas absolutny; pominięcie argumentu używa timera. EffectPass akumuluje material.time += deltaTime*timeScale, a GlitchEffect losuje Math.random. Alfa i edytowalność zależą od scene/targets.','SRC01','SRC02','SRC03'),v('R04','GPU WebGL/Three peer >=0.168.0 <0.188.0. README zaleca HalfFloatType dla HDR-like pipeline, właściwy outputColorSpace oraz tonemapping na końcu. Node >=24 i pnpm >=12 <13 to devEngines repo, nie dowód wymagań browser runtime. VRAM skaluje się z targetami; pomiar Unknown.'+LIMIT,'PACKAGE','README'),EXPORT,v('R04','Brak opłat/konta/klucza dla library. Demo ma zewnętrzne media, nie pobrano. Scripts build/test/prepublishOnly, brak install/postinstall/prepare w manifest. Peer Three; narzędzia dev obejmują Hugo i shader bundling. DERIVED 2–4 dni dla wybranych efektów; stanowy glitch poza zakresem.','PACKAGE'),v('R04','Zlib: zachować notice, oznaczyć zmiany i nie przypisywać sobie autorstwa. '+PERM,'LICENSE'),v('R04','HEAD 2026-11-01, 6.39.6. Czytano composer/pass/glitch/noise; nie audytowano wszystkich efektów, shaderów ani transitive deps. Publiczne demo nie dowodzi seek/export.','META','SRC01','SRC02','SRC03','SRC04'),'ADAPTER','P1: dopuścić wyłącznie whitelistę efektów bez historii po testach; autoritative time adapter per effect. Glitch i akumulujące historię efekty odłożyć do bake/cache.','3 s kontrastowy obiekt i SDF tekst, glow przy krawędzi, półprzezroczystość; frame order permutation, dwukrotny capture tej samej klatki, black/white composite; compare flat gradient w U8/HalfFloat i tone map raz. 16:9/9:16, 4K stress; temporal watch bloom/shimmer, GPU i pamięć logowane.',True)
card('R05','pixi-filters — kontrolowany CRT i ograniczenia glitch','PixiJS Team','KNOWN_NEW_CAPABILITY','CRT/scanlines i wybrane stylizacje w już używanym Pixi.','Baseline ma Pixi i PixelFX; nowa delta ogranicza się do jawnych time/seed uniformów CRT i wniosku o nieseedowanej geometrii glitch. Ogólny katalog pixel/glitch już pokryty.',v('R05','src/crt/CRTFilter.ts; src/glitch/GlitchFilter.ts; subpath import pixi-filters/crt.','SRC01','SRC02','PACKAGE'),v('R05','IN tekstura/Pixi container, parametry CRT time/seed/noise/vignette; OUT filtered texture. apply kopiuje time/seed do uniformów. Glitch seed to uSeed; bands/shuffle/offsets nadal Math.random, więc seed nie kontroluje całego obrazu. Alfa po filtrze do sprawdzenia.','SRC01','SRC02'),v('R05','Pixi >=8.0.0-0 peer; WebGL GPU, TS/JS. CRT ma ścieżki programów GL/GPU w pliku; rzeczywiste wsparcie wybranego backendu i headless Unknown.'+LIMIT,'PACKAGE','SRC01'),EXPORT,v('R05','Bez konta/klucza/usługi; offline z lokalnymi teksturami. Manifest 6.1.5: @types/gradient-parser runtime declaration, Pixi peer; brak install hook w scripts; dev screenshots używa Electron. DERIVED 1–2 dni dla CRT.','PACKAGE'),v('R05','MIT kod. '+PERM,'LICENSE'),v('R05','HEAD 2025-11-29, 6.1.5. Dokładny shader/backend coverage i alpha nie były odpalone. Tylko seed uniform nie stanowi dowodu determinism.','META','SRC02'),'ADAPTER','P1 CRT-only; glitch odrzucić z pilota bez pełnego seedowania/prebake. Bez dodatkowej biblioteki dla blur/alpha obecnych w Pixi.','CRT frame-derived time na siatce i cienkich liniach, 60 klatek loop; powtórzony seed i frame; glitch negative-control ma ujawnić różnice nowych instancji. 16:9/9:16, dwa tła, pełny ogląd scanline aliasing/flicker.')
card('R06','simplex-noise — pole proceduralne z deterministycznym seedem','jwagner / Jonas Wagner','NEW','Powtarzalne tła, organiczne trajektorie i sterowanie parametrami bez symulacji zależnej od kolejności klatek.','Baseline ma PixelFX/generative efekty, lecz nie wskazuje geometry-only seeded 2D/3D/4D noise API. Nowa pozycja to ten mały moduł, nie nowa kategoria generative art.',v('R06','simplex-noise.ts: createNoise2D/3D/4D(random), buildPermutationTable.','SRC01'),v('R06','IN współrzędne i funkcja PRNG przy inicjalizacji; OUT scalar noise, brak obrazu/alpha. Domyślnie Math.random, seed trzeba dostarczyć. Po zbudowaniu permutation table wynik zależy od współrzędnych. Parametry x/y/częstotliwość/amplituda/czas należą do hosta.','README','SRC01'),v('R06','CPU JS browser/Node, ESM/CJS; bez declared runtime dependencies. GPU potrzebny tylko dla wybranego host renderera. Stan ograniczony do tablic; exact RAM/throughput Unknown.'+LIMIT,'PACKAGE'),EXPORT,v('R06','Bez konta/klucza/sieci po przypięciu. Alea jest przykładem PRNG/devDependency, nie runtime dependency; wybrany PRNG wymaga własnego pinu/praw. prepare wywołuje build.sh: mkdir, dwa tsc builds i zapis esm package marker. Brak pobierania usług w odczytanym build.sh. DERIVED 0.5–1 dzień.','PACKAGE','SRC02','README'),v('R06','MIT kod. '+PERM,'LICENSE'),v('R06','HEAD 2024-07-26, 4.0.3. README ostrzega, że 4.x zmienia output względem 3.x; wspólna instancja PRNG dla kilku create calls zmienia sekwencję w porównaniu z osobnymi. Nie obiecywać starych hashów po upgrade.','META','README'),'OPTIONAL_DEPENDENCY','P0: mały helper dla czystego noiseAt(frame,coords,seed), PRNG i parametry w manifest. Loop na okręgu w 4D to własna reguła DERIVED, nie wbudowany exporter.','2 s/60 klatek Najpierw k=((f%N)+N)%N, potem theta=2πk/N i noise4D(x*s,y*s,r*cos(theta),r*sin(theta)); f=N i f=0 mają identyczny k=0. Nie zakładać exact sin(2π)=0; eksport 0..N-1 bez duplikatu. Shuffled seek i drugi proces ten sam seed→identyczne raw field; inny seed różny. 16:9/9:16, temporal ogląd szwu, banding i high-frequency aliasing.',True)
card('R07','Zdog — referencja pseudo-3D Canvas/SVG','metafizzy / David DeSandro','ALREADY_COVERED','Prosta płaska ilustracja pseudo-3D z obrotami, bez PBR.','Baseline ma Three/Canvas i explainery, a nie wykazano konkretnej luki uzasadniającej kolejny engine. Przydatna tylko metoda renderowania geometrycznych ilustracji.',v('R07','js/illustration.js updateRenderGraph i istniejący API Anchor/Shape.','SRC01'),v('R07','IN drzewo figur, translate/rotate/scale; OUT Canvas2D lub SVG. Dema mają dragRotate i rotate +=, więc adapter musiałby ustawiać rotate=f(frame), wyłączyć drag i jawnie renderować. SVG pozostaje edytowalne; alfa wynikowa nie sprawdzona.','README','SRC01'),v('R07','JS CPU geometry + Canvas2D/SVG browser; headless zależne od browser. W package 1.1.3 brak runtime deps i install hooks.'+LIMIT,'PACKAGE'),EXPORT,v('R07','Brak konta/klucza/usługi dla library; offline local bundle. DERIVED 1–2 dni, lecz brak uzasadnienia kosztu wobec baseline.','PACKAGE'),v('R07','MIT deklarowane przez README i package (osobnego LICENSE w tym odczycie nie ustalono). Media CodePen/galerii, font Zfont i cudze modele osobne Unknown. Nie redystrybuować galerii na podstawie README. Własny film i source bundle rozdzielić.','README','PACKAGE'),v('R07','HEAD 2022-01-22, 1.1.3; README nazywa v1 beta. Brak współczesnego wykonawczego dowodu.','META','README'),'KNOWLEDGE_ONLY','P2: zasada pseudo-3D przez grube linie/koła; nie dodawać pełnego engine ani Toolbox entry.','Gdy pojawi się uzasadniony brief: jedna ikona cube+ring obrót z frame, SVG/Canvas porównanie, 16:9/9:16 i bez interakcji. Ogląd przecinających się figur i sortowania głębi.')
card('R08','three.quarks — particles, kandydat dopiero po bake','Alchemist0823 / Forrest Sun','KNOWN_NEW_CAPABILITY','Batched particle/trail VFX w scenach Three.','Baseline zna Three i procedural effects; delta to wyspecjalizowany emitter/behaviour system. Nie wykazano gotowości do losowego seek filmu.',v('R08','packages/three.quarks/src/ParticleSystem.ts i quarks.core/src/functions/IntervalValue.ts.','SRC02','SRC03'),v('R08','IN emitter, start values, behaviours, tekstura i delta; OUT live particles/batch. update integruje pozycję i wiek, ogranicza delta do 0.1; restart resetuje część stanu, ale IntervalValue używa Math.random. Brak potwierdzonego seed/seek contract. Parametry JSON edytowalne; alpha przez material/texture.','SRC02','SRC03','README'),v('R08','Three >=0.182.0 peer, CPU simulation + GPU render. quarks.core dependency ma wildcard *, wymagany pełny lock. prepare=husky w subpackage; monorepo workspace build jest większy niż runtime.'+LIMIT,'SRC01','PACKAGE'),EXPORT+' Wymaga DERIVED deterministic replay od t=0 lub cache/bake; nie wystarczy render(delta=absoluteTime).',v('R08','Kod MIT bez klucza; ceny/konto/licencja osobnego edytora quarks.art Unknown, edytora nie rekomendujemy jako wymogu. DERIVED >=4–7 dni na seed audit/replay/cache; nie przewidywano instalacji.','README','SRC01'),v('R08','MIT kod, nie automatycznie licencja sprite textures, modeli ani eksportowanych presetów edytora. '+PERM,'LICENSE'),v('R08','HEAD 2026-05-21, three.quarks 0.17.1. Czytano wycinek generatora i ParticleSystem, nie wszystkie behaviours. Brak gwarancji determinism po samym restart().','META','SRC02','SRC03'),'KNOWLEDGE_ONLY','P2 / HOLD runtime: najpierw dowód kompletnego seedowania i reprodukcji. Przy prostym motion użyć czystej parametrycznej geometrii zamiast symulacji.','100 particles, fixed delta 1/60; dwa niezależne uruchomienia i restart do frame 90; hash positions, particle counts i obrazu; shuffled order przez cache. Stress pamięci i alpha edges, loop nie deklarować dopóki nie zbadano szwu.')
card('R09','resvg-js — lokalna rasteryzacja klatek SVG','thx / projekt resvg-js (historyczne odwołania yisibl)','NEW','Render seryjnych, statycznych SVG do PNG bez browser layoutu i bez zależności od systemowych fontów.','Baseline ma SVG/canvas i mediabunny, lecz odczytane karty nie wskazują konkretnego CPU SVG→PNG rasterizera z kontrolą font files. To adapter eksportowy, nie nowy engine animacji.',v('R09','src/lib.rs/options.rs/fonts.rs, index.d.ts, js-binding.js. Resvg(svg,opts).render().asPng(); imagesToResolve/resolveImage.','SRC01','SRC02','SRC03','SRC05','SRC06'),v('R09','IN SVG String/Buffer, fitTo/crop/background, fontFiles i loadSystemFonts; OUT PNG/RGBA, uproszczony SVG i bounds. Pojedynczy dokument statyczny; wrapper nie daje czasu SMIL/CSS. Ruch powstaje przez nowy SVG dla frame. Alfa wymaga decode/kompozycji testowej; raw pixels nie traktować bez sprawdzenia jak straight RGBA.','SRC01','SRC02','SRC06'),v('R09','CPU native napi-rs dla Node; manifest Node >=10, to deklaracja, nie współczesny test wszystkich Node. Prebuilt targets obejmują macOS arm64/x64, Linux i Windows; osobny WASM route. js-binding wybiera local/platform package; Linux libc fallback może wywołać ldd. RAM/OS/zgodność hosta Unknown.','PACKAGE','SRC05'),v('R09','Bezpośredni PNG (asPng); DERIVED sekwencja PNG z frame-derived SVG → istniejący FFmpeg/encoder MP4 lub WebM. Nie renderuje interaktywnej strony; EXR brak udokumentowanego output. PNG z alphą do przyszłego decode QA.','SRC06'),v('R09','Kod bez konta/klucza/usługi; lokalne fonty i obrazy umożliwiają offline po przygotowaniu. README no postinstall; package ma build/prepublishOnly, bez install hook. Cargo ma git rev resvg i branch woff2 patch: kontrola lock/release artefact, nie runtime download branch przez gotową binarkę. DERIVED 2–3 dni plus stress native memory.','PACKAGE','SRC04','SRC05','README'),v('R09','MPL-2.0 kod: publikacja covered source/binary wymaga spełnienia §3 source availability/notices; większy program może mieć inną licencję. Sam film z własnego SVG nie jest dystrybucją renderer source. Fonty/model/obraz/przykładowy SourceHan font osobne Unknown. Nie kopiować example fonts bez licencji.','LICENSE')+' '+ref('RW_MPL'),v('R09','HEAD 2026-03-26; manifest 2.7.0-alpha.2, nie stabilna rekomendacja. #421 raportuje memory retention 2.6.2/alpha.2; #423 abort 2.6.2. Odczytany lib.rs ma external memory accounting/catch unwind, lecz nie dowodzi naprawy żadnego issue. NOT_RUN.','META','PACKAGE','ISSUE421','ISSUE423','SRC01'),'ADAPTER','P0 kwalifikacja eksportu, ale HOLD production do font/alpha/memory i crash QA. Pin binary+platform package+hash zgodny ze source; wybór stabilnej wersji osobno. Renderer fallback tylko jawny, z osobnym baseline obrazu.','SVG własna geometria + Zażółć gęślą jaźń + gradient/maska/blur; lokalny font z hashem, loadSystemFonts=false, no network. 180 klatek 1080p i 4K stress w izolowanym workerze; peak/RSS trend i brak abort. PNG decode dimensions/alpha; composite white/black; shuffled frame, porównanie browser/resvg jako oddzielne oracle, 16:9/9:16.',True)
card('R10','pixelmatch — obrazowy comparator do obecnego QA','mapbox / Volodymyr Agafonkin','KNOWN_NEW_CAPABILITY','Lokalizacja różnic pomiędzy tym samym frame po rewind i między preview/export.','Baseline ma motion QA i pixel diff; delta to przypięty comparator v8 z jawną polityką AA/alpha/threshold, nie nowy system oceny jakości.',v('R10','index.js pixelmatch(img1,img2,output,w,h,options); CLI bin deklarowany, nie odczytany.','SRC01','PACKAGE'),v('R10','IN RGBA arrays o równych rozmiarach; OUT liczba różnic lub max local-window oraz diff. threshold to różnica koloru per pixel, nie procent obrazu. Default includeAA=false; checkerboard=true wpływa na alpha porównanie. Parametr alpha steruje tłem diff, nie eksportem alfy.','README','SRC01'),v('R10','JS CPU browser/Node; core operuje na arrays; package ma pngjs runtime dependency dla ścieżki PNG/CLI mimo README no-dependencies claim o core. Scripts pretest/test bez install hooks.'+LIMIT,'PACKAGE','README'),v('R10','Wytwarza diff pixels, PNG po zewnętrznym zapisie; brak filmu. Wpiąć do obecnego QA po decode klatek; MP4/WebM i EXR nie są inputem API bez dekodera.','README'),v('R10','ISC library bez konta/klucza/sieci przy lokalnych arrays. DERIVED 0.5–1 dzień, tylko gdy obecny comparator nie daje tej funkcji.','LICENSE'),v('R10','ISC code: zachować notice. '+PERM,'LICENSE'),v('R10','HEAD 2026-10-06; package 8.0.0. Metryka OKLab/HyAB opisana w README, nie zakładać zgodności progów ze starszymi wersjami. Nie mierzy czytelności, rytmu ani poprawności praw do assetu.','META','PACKAGE','README'),'SKILL_ADAPTATION','P0: doprecyzować politykę exact-vs-tolerant w obecnym QA; helper OPTIONAL_DEPENDENCY dopiero jeśli obecny moduł nie ma porównywalnej funkcji.','Known-equal frame, single-pixel mutation, AA-only mutation i RGB przy alpha=0; osobno hash raw/decoded i perceptual diff. Kontrolne błędy muszą zostać wykryte. Ogląd pełnej sekwencji i diff overlay, nie tylko zerowy count.')
card('R11','MeshLine — grube 3D linie i trails','pmndrs / autor oryginału Jaume Sanchez','DUPLICATE/FORK','Variable-width/dashed linie billboardowane w Three zamiast platformowego GL_LINE.','README wprost fork spite/THREE.MeshLine; brak wykazanej przewagi nad istniejącą ścieżką Three dla celu FrameCore. Zachować jako comparator, nie samodzielną nowość.',v('R11','src/MeshLineGeometry.ts setPoints/advance; MeshLineMaterial API w README.','SRC01','README'),v('R11','IN points i widthCallback, dashOffset/resolution/opacity; OUT triangle-strip mesh. advance usuwa najstarszy punkt i akumuluje historię, dlatego DERIVED trail odtwarzać z deterministycznej listy punktów dla frame. Nie kopiować README widthCallback z Math.random. Alfa zależy od material, depth i blending.','SRC01','README'),v('R11','Three >=0.137 peer, WebGL GPU. Brak install hooks w scripts build/dev. CPU koszt przebudowy points; headless/VRAM Unknown.'+LIMIT,'PACKAGE'),EXPORT,v('R11','MIT bez konta/klucza. Offline z własnymi teksturami. DERIVED 1–2 dni, bez uzasadnienia przed porównaniem baseline.','PACKAGE'),v('R11','MIT fork z notice oryginalnego autora. '+PERM,'LICENSE'),v('R11','HEAD 2024-06-03, 3.3.1. README deklaruje BufferGeometry input, kod convertPoints wymaga osobnego kompatybilności testu, nie przyjmować całej listy input za sprawdzoną.','META','README','SRC01'),'KNOWLEDGE_ONLY','P2: pattern trailAtFrame; nie dodawać forka tylko dla nazwy. Potencjalny mały adapter po dowodzie lepszej jakości niż obecne Three lines.','Zmienne width i dash, ostry zakręt, transparent trail na przecięciach; frame order [90,0,89,90], portrait/wide resolution; ogląd aliasingu i depth sorting w całym klipie.')
card('R12','opentype.js — kontury glifów do geometry motion','opentypejs / Frederik De Bleser i contributors','KNOWN_NEW_CAPABILITY','Uzyskanie krzywych i metryk glifu do deformacji, outline reveal i kontrolowanego layoutu.','Baseline ma SplitText i text QA; delta to data-level font outlines, nie kolejny mechanizm rozdzielania DOM liter.',v('R12','src/font.mjs getPath/getPaths/getAdvanceWidth/stringToGlyphs; parse font bytes.','SRC01','README'),v('R12','IN OTF/TTF/WOFF i tekst; OUT path(s)/metrics/glyphs. Zachowuje kompozytowe litery według docs; ligatury oznaczają, że glyph≠character. Edytowalne krzywe, ale prawa fontu nadal obowiązują. WOFF2 wymaga osobnego dekompresora, nie native parse. Alfa N/A dla geometry.','README','SRC01'),v('R12','Browser/Node CPU; plik package bez version, pin commit jest identyfikatorem. Brak declared runtime dependencies; WOFF2 przykład pobiera osobny WASM/decompress script. Scripts build/test, bez install hook.'+LIMIT,'PACKAGE','README'),EXPORT+' DERIVED eksport ścieżek do SVG w host adapterze; sama biblioteka nie koduje wideo.',v('R12','Bez konta/klucza dla parsera; fonty mogą kosztować i mieć ograniczenia embeddingu. Preferować lokalne TTF/OTF, nie CDN WOFF2 przykład. DERIVED 1–2 dni + typographic QA.','README'),v('R12','MIT kod, ale test/fonts/LICENSE podaje OFL-1.1, Apache-2.0 (Roboto) oraz CC BY-SA 4.0 (OpenMoji subset) per plik. Font-source redistribution, outline-derived asset i renderowany film oceniać osobno według konkretnej licencji. Nie importować folderu test/fonts jako MIT assets. Modele/pozostałe media Unknown; przykładowy kod repo pod notice.','LICENSE','SRC02'),v('R12','HEAD 2026-05-19; poprawka checksum nie jest testem wszystkich fontów. Manifest nie zawiera package version. Brak dowodu zgodności layoutu z browser shaping dla każdego skryptu; sprawdzić właściwy język/ligatury.','META','PACKAGE','SRC01'),'OPTIONAL_DEPENDENCY','P1: wąski outline extraction contract przy rzeczywistej potrzebie deformacji glifów. Dla prostego text reveal korzystać z obecnego HTML/font workflow.','Polski NFC/NFD, AV kerning, fi ligature, Ł/ą/ź i missing glyph; bounds, number of glyphs vs graphemes, porównanie z zatwierdzonym wzorcem fontu; same layout po shuffled seek, full reveal i clipping w 16:9/9:16.')
